#!/usr/bin/env python3
"""MRCR response pool regeneration (v3, 2026-10-05): generated by the model to be trained itself (thinking off), replacing the earlier pool generated by Instruct-2507.

Same method as the original mrcr_synth_v2/generate_response_pool.py: prompt "write a {format} about {entity}",
438 entities × 10 formats × 100 responses per combination, temperature 0.95, max_tokens 1024, single turn, no system prompt.
The only differences are how thinking is turned off and how output is written:
  --mode template : chat API + chat_template_kwargs.enable_thinking=False (hybrid thinking models such as Qwen3-8B;
                    the template inserts "<think>\\n\\n</think>\\n\\n" automatically)
  --mode prefill  : completions API, prompt = chat template (add_generation_prompt) + "\\n</think>\\n\\n"
                    (the Qwen3-4B-Thinking-2507 template always ends with "<think>\\n" and ignores enable_thinking;
                    with this suffix the format is verbatim identical to a hybrid model with thinking off)
  Observed (2026-10-05): 2507 does not accept an empty thinking block; after the prefill it still writes a reasoning
  passage and then </think> before answering. With a 1024-token budget 54% were truncated and 0.9% never reached
  </think> (the stored text was reasoning). Therefore prefill mode raises the budget to --max_tokens 3072 and keeps only
  the answer after the last </think>; outputs without </think> are invalid, resampled (at most 3 times), then dropped.
  Output is appended one record at a time (the original script rewrote the whole file every 100 records, O(n^2) at
  430k records); --resume fills up to the existing count.
Each record also stores finish_reason and think_leak (</think> appears again in the output, i.e. thinking was not fully
turned off); these are recorded but not filtered, as in the original pipeline.
"""
import argparse, json, os, random, sys, threading, time
from collections import Counter
from concurrent.futures import ThreadPoolExecutor, as_completed
from openai import OpenAI

ap = argparse.ArgumentParser()
ap.add_argument("--model_path", required=True)
ap.add_argument("--mode", choices=["template", "prefill"], required=True)
ap.add_argument("--output_path", required=True)
ap.add_argument("--url", default="http://127.0.0.1:8000/v1")
ap.add_argument("--entities_path", default="synthesis/entities.json")
ap.add_argument("--formats_path", default="synthesis/formats.json")
ap.add_argument("--num_per_combo", type=int, default=100)
ap.add_argument("--max_tokens", type=int, default=1024)
ap.add_argument("--temperature", type=float, default=0.95)
ap.add_argument("--workers", type=int, default=256)
ap.add_argument("--limit", type=int, default=0, help="smoke test: generate only this many records")
ap.add_argument("--shard", type=int, default=0, help="multi-node parallelism: this process only handles combinations whose index %% nshard == shard")
ap.add_argument("--nshard", type=int, default=1)
args = ap.parse_args()

entities = json.load(open(args.entities_path))
formats = json.load(open(args.formats_path))
combos = [(f, e) for f in formats for e in entities]
client = OpenAI(api_key="EMPTY", base_url=args.url, timeout=600)

tok = None
if args.mode == "prefill":
    from transformers import AutoTokenizer
    tok = AutoTokenizer.from_pretrained(args.model_path)

import glob
have = Counter()
base = args.output_path[:-len(".jsonl")] if args.output_path.endswith(".jsonl") else args.output_path
for fp in sorted(set(glob.glob(base + ".jsonl") + glob.glob(base + ".s*.jsonl"))):  # count the main file and all shard files together
    for l in open(fp, encoding="utf-8"):
        try:
            r = json.loads(l); have[(r["format"], r["entity"])] += 1
        except Exception:
            pass
tasks = [c for i, c in enumerate(combos) if i % args.nshard == args.shard
         for _ in range(max(0, args.num_per_combo - have[c]))]
if args.nshard > 1:
    args.output_path = f"{base}.s{args.shard}.jsonl"
random.seed(0); random.shuffle(tasks)
if args.limit:
    tasks = tasks[:args.limit]
print(f"entities={len(entities)} formats={len(formats)} combos={len(combos)} existing={sum(have.values())} todo={len(tasks)} mode={args.mode}", flush=True)


def gen(fmt, ent):
    prompt = f"write a {fmt} about {ent}"
    msgs = [{"role": "user", "content": prompt}]
    for attempt in range(3):
        try:
            if args.mode == "template":
                c = client.chat.completions.create(model=args.model_path, messages=msgs, max_tokens=args.max_tokens,
                                                   temperature=args.temperature,
                                                   extra_body={"chat_template_kwargs": {"enable_thinking": False}})
                text, fr = c.choices[0].message.content or "", c.choices[0].finish_reason
                ntok = c.usage.completion_tokens
            else:
                p = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)
                assert p.endswith("<think>\n"), p[-40:]
                c = client.completions.create(model=args.model_path, prompt=p + "\n</think>\n\n",
                                              max_tokens=args.max_tokens, temperature=args.temperature)
                text, fr = c.choices[0].text or "", c.choices[0].finish_reason
                ntok = c.usage.completion_tokens
            leak = "</think>" in text
            if args.mode == "prefill" and not leak:
                raise ValueError("no </think> within budget (still reasoning)")
            if leak:
                text = text[text.rfind("</think>") + len("</think>"):]
            text = text.strip()
            if text:
                return {"format": fmt, "entity": ent, "response": text, "finish_reason": fr,
                        "think_leak": leak, "completion_tokens": ntok}
        except Exception as e:
            if attempt == 2:
                if "no </think>" not in str(e):
                    print(f"FAIL {fmt} | {ent}: {e}", flush=True)
            time.sleep(1)
    return None


lock = threading.Lock()
out = open(args.output_path, "a", encoding="utf-8")
t0 = time.time(); done = 0; ntok = 0; nlen = 0; nleak = 0
with ThreadPoolExecutor(max_workers=args.workers) as ex:
    futs = [ex.submit(gen, f, e) for f, e in tasks]
    for fu in as_completed(futs):
        r = fu.result()
        with lock:
            done += 1
            if r:
                out.write(json.dumps(r, ensure_ascii=False) + "\n")
                ntok += r["completion_tokens"]; nlen += r["finish_reason"] == "length"; nleak += r["think_leak"]
            if done % 2000 == 0 or done == len(tasks):
                out.flush()
                el = time.time() - t0
                eta = el / done * (len(tasks) - done)
                print(f"PROGRESS {done}/{len(tasks)} {done/el:.1f} req/s {ntok/el:.0f} tok/s "
                      f"avg_tok={ntok/max(1,done):.0f} truncated={nlen} think_leak={nleak} "
                      f"elapsed={el/3600:.2f}h eta={eta/3600:.2f}h", flush=True)
out.close()
print(f"POOL_DONE n={done} truncated={nlen} think_leak={nleak} hours={(time.time()-t0)/3600:.2f}", flush=True)
